import {parseSkill,validateSkill} from './github-skills-core.js?v=20261027review';
import {discoverGithubSkills,loadGithubSkill} from './github-skills-loader.js?v=20261027review';
import {getActiveSkill,getSkillMode,setActiveSkill} from './github-skills-state.js?v=20261027review';
import {applyEditingSkill} from './app.js?v=20261027review';
const $=id=>document.getElementById(id),storageKey='clippilot-github-skills-v1';let discovery=null,current=null,library=[],reading=false;
const say=t=>$('github-skill-status').textContent=t;
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function identity(s){return s.source.url||s.name+'\n'+s.markdown.slice(0,100)}
function save(){if(!current)throw Error('请先加载 Skill');const next=[current,...library.filter(s=>identity(s)!==identity(current))].slice(0,20);localStorage.setItem(storageKey,JSON.stringify(next));library=next;renderLibrary()}
function renderLibrary(){const select=$('github-skill-library');select.replaceChildren();library.forEach((s,i)=>{const op=document.createElement('option');op.value=i;op.textContent=s.name+' · '+(s.source.commit?s.source.commit.slice(0,7):'本地文件');select.append(op)});$('github-skill-count').textContent=`已保存 ${library.length}/20 份 Skill；清除浏览器数据会丢失，请备份。`}
function show(skill){current=validateSkill(skill);$('github-skill-name').textContent=current.name;$('github-skill-description').textContent=current.description||'没有可直接显示的单行描述，请查看完整说明。';$('github-skill-preview').textContent=current.markdown;const source=$('github-skill-source');source.replaceChildren();if(current.source.url){const a=document.createElement('a');a.href=current.source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=current.source.repository+' / '+current.source.path+' · 固定版本 '+current.source.commit.slice(0,7);source.append(a)}else source.textContent='本地上传，未核验 GitHub 来源。';$('github-skill-capability').textContent=(current.recipe?'包含 ClipPilot 参数预设，可生成规则初稿。':'普通 Markdown：可交给本地 AI 作为剪辑指导，公开版不会自动执行文字要求。')+(current.runtimeHints?' 检测到脚本、依赖或附加资料线索；这些文件尚未载入或执行。':'');$('github-skill-recipe').textContent=current.recipe?JSON.stringify(current.recipe,null,2):'无 ClipPilot 参数预设。';$('github-skill-apply').disabled=!current.recipe;const list=$('github-skill-requirements');list.replaceChildren();current.requirements.forEach(t=>{const li=document.createElement('li');li.textContent=t;list.append(li)});$('github-skill-detail').hidden=false}
async function readTask(fn){if(reading)return;reading=true;const controls=[...$('github-skills-panel').querySelectorAll('button,input,select')],states=new Map(controls.map(e=>[e,e.disabled]));controls.forEach(e=>e.disabled=true);try{await fn()}catch(e){say(e.message)}finally{reading=false;states.forEach((disabled,e)=>e.disabled=disabled);$('github-skill-apply').disabled=!current?.recipe}}
$('github-skill-discover').onclick=()=>readTask(async()=>{say('正在读取公开仓库并固定提交版本…');discovery=await discoverGithubSkills($('github-skill-url').value,$('github-skill-ref').value);const paths=$('github-skill-path');paths.replaceChildren();discovery.paths.forEach(path=>{const op=document.createElement('option');op.value=path;op.textContent=path;paths.append(op)});$('github-skill-choice').hidden=false;if(discovery.paths.length===1){show(await loadGithubSkill(discovery,discovery.paths[0]));say('Skill 已读取，请检查说明后启用；未执行仓库代码。')}else say(`发现 ${discovery.paths.length} 份 Skill，请选择再读取。${discovery.truncated?'目录结果不完整，可使用具体文件链接。':''}`)});
$('github-skill-load').onclick=()=>readTask(async()=>{if(!discovery)throw Error('请先发现仓库内的 Skill');show(await loadGithubSkill(discovery,$('github-skill-path').value));say('已读取所选 Skill；请检查说明后启用。')});
$('github-skill-upload').onchange=e=>readTask(async()=>{try{const file=e.target.files[0];if(!file)return;if(file.size>64000)throw Error('SKILL.md 文件需小于 64KB');show(parseSkill(await file.text()));say('本地 Skill 已读取，未执行其中代码。')}finally{e.target.value=''}});
$('github-skill-save').onclick=()=>{try{save();say('Skill 已保存到当前浏览器，可以备份。')}catch(e){say('保存失败：'+e.message)}};
$('github-skill-open-saved').onclick=()=>{try{const s=library[Number($('github-skill-library').value)];if(!s)throw Error('没有可载入的 Skill');show(s);say('已载入保存版本，尚未启用。')}catch(e){say(e.message)}};
$('github-skill-delete').onclick=()=>{try{if(!library.length)throw Error('没有可删除的 Skill');const s=library[Number($('github-skill-library').value)],next=library.filter(x=>x!==s);localStorage.setItem(storageKey,JSON.stringify(next));library=next;renderLibrary();say('已从保存列表删除；如需停用当前指导，点击“停用 Skill”。')}catch(e){say(e.message)}};
$('github-skill-activate').onclick=()=>{try{if(!current)throw Error('请先加载 Skill');setActiveSkill(current);say('已启用为本地 AI 指导。需要在本地版运行视觉模型；未执行脚本或附加资源。')}catch(e){say(e.message)}};
$('github-skill-apply').onclick=async()=>{try{if(!current?.recipe)throw Error('这份 Skill 没有 ClipPilot 参数预设');const ok=await applyEditingSkill(current);say(ok?'已按预设生成初稿；在时间线核对后导出。':'预设已载入；若未导入素材，请先导入视频，再生成初稿。')}catch(e){say(e.message)}};
$('github-skill-disable').onclick=()=>{setActiveSkill(null);say('已停用后续生成的 Skill 指导，已有时间线保留。')};
document.addEventListener('editing-skill-change',()=>{const active=getActiveSkill();$('github-skill-active').textContent=active?'当前指导：'+active.name+(getSkillMode()==='preset'?' · 规则参数预设':' · 本地 AI 文字指导')+'（不会自动执行脚本）':'当前未启用 Skill'});
$('github-skill-backup').onclick=()=>download(JSON.stringify({type:'clippilot-skill-library',version:1,skills:library},null,2),'ClipPilot-Skills.json','application/json');
$('github-skill-restore').onchange=e=>readTask(async()=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Skill 备份需小于 2MB');const data=JSON.parse(await file.text());if(data.type!=='clippilot-skill-library'||data.version!==1||!Array.isArray(data.skills)||data.skills.length>20)throw Error('备份格式无效');const incoming=data.skills.map(validateSkill),next=[...incoming,...library].filter((s,i,a)=>a.findIndex(x=>identity(x)===identity(s))===i).slice(0,20);localStorage.setItem(storageKey,JSON.stringify(next));library=next;renderLibrary();say('已恢复 Skill 库；请载入一份并手动启用。')}finally{e.target.value=''}});
$('github-skill-export').onclick=()=>{if(!current)return say('请先读取 Skill');download(current.markdown,'SKILL.md','text/markdown;charset=utf-8')};
$('github-skill-example').onclick=()=>{show(parseSkill('---\nname: product-rhythm-example\ndescription: 演示参数如何接入粗剪，文案需要与实际画面核对。\n---\n# 产品展示节奏示例\n- 先展示使用场景，再展示过程和细节。\n- 不编造性能或数字。\n- 预览并校正文案后再导出。\n\n```clippilot\n{"version":1,"style":"explain","kind":"product","target":15,"ratio":"16:9","captions":["从一个使用场景开始","展示实际操作过程","把关键细节看清楚","回到这次展示的主题"]}\n```\n'));say('已载入内置格式示例，尚未启用。它不是从 GitHub 读取的作品。')};
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(saved)||saved.length>20)throw Error('Skill 库格式异常');library=saved.map(validateSkill)}catch(e){say('保存内容未恢复：'+e.message)}renderLibrary();
$('github-skill-shortcut').onclick=()=>{$('github-skills-panel').scrollIntoView({behavior:'smooth',block:'start'})};
